#region Purpose
// TWA0004 cases: missing Purpose warns; any Purpose region is enough; generated files are skipped.
#endregion

namespace TimeWarp.SourceGenerators.AnalyzerTests;

internal static class PurposeRegionAnalyzerTests
{
  public static readonly (string Name, Func<Task> Body)[] Cases =
  [
    ("missing purpose region warns", MissingPurpose_Should_ReportTwa0004),
    ("purpose region is clean", PurposeRegion_Should_BeClean),
    ("nested purpose region is clean", NestedPurposeRegion_Should_BeClean),
    ("other region name warns", OtherRegionName_Should_ReportTwa0004),
    ("generated file is clean", GeneratedFile_Should_BeClean)
  ];

  public static async Task MissingPurpose_Should_ReportTwa0004()
  {
    const string source =
      """
      namespace Contracts;

      public class Widget
      {
        public string Name { get; set; } = null!;
      }
      """;

    ImmutableArray<Diagnostic> diagnostics = await AnalyzeAsync("Widget.cs", source);
    Expect.Equal(1, diagnostics.Length, "A file without #region Purpose should warn.");
    Expect.Equal(PurposeRegionAnalyzer.DiagnosticId, diagnostics[0].Id, "Id stays TWA0004.");
    Expect.Contains("Widget.cs", diagnostics[0].GetMessage(), "Message names the file.");
    Expect.Span(diagnostics[0], 1, 1, 10, "Diagnostic anchors on the namespace token.");
  }

  public static async Task PurposeRegion_Should_BeClean()
  {
    const string source =
      """
      #region Purpose
      // A widget shape used to verify the analyzer accepts a top-of-file region.
      #endregion

      namespace Contracts;

      public class Widget
      {
        public string Name { get; set; } = null!;
      }
      """;

    ImmutableArray<Diagnostic> diagnostics = await AnalyzeAsync("Widget.cs", source);
    Expect.Equal(0, diagnostics.Length, "A top-of-file Purpose region is enough.");
  }

  public static async Task NestedPurposeRegion_Should_BeClean()
  {
    const string source =
      """
      namespace Contracts;

      public class Widget
      {
        #region Purpose
        // Region nested inside the type still counts.
        #endregion
        public string Name { get; set; } = null!;
      }
      """;

    ImmutableArray<Diagnostic> diagnostics = await AnalyzeAsync("Widget.cs", source);
    Expect.Equal(0, diagnostics.Length, "Placement is not part of the rule.");
  }

  public static async Task OtherRegionName_Should_ReportTwa0004()
  {
    const string source =
      """
      #region Design
      // Design alone is not enough; Purpose is the universal requirement.
      #endregion

      namespace Contracts;

      public class Widget;
      """;

    ImmutableArray<Diagnostic> diagnostics = await AnalyzeAsync("Widget.cs", source);
    Expect.Equal(1, diagnostics.Length, "A Design region does not satisfy Purpose.");
    Expect.Span(diagnostics[0], 5, 1, 10, "Diagnostic anchors on the namespace token after the region.");
  }

  public static async Task GeneratedFile_Should_BeClean()
  {
    const string source =
      """
      // <auto-generated/>
      namespace Contracts;

      public class Widget;
      """;

    ImmutableArray<Diagnostic> diagnostics = await AnalyzeAsync("Widget.g.cs", source);
    Expect.Equal(0, diagnostics.Length, "Generated trees are skipped.");
  }

  private static Task<ImmutableArray<Diagnostic>> AnalyzeAsync(string fileName, string source) =>
    AnalyzerTestDriver.AnalyzeAsync(new PurposeRegionAnalyzer(), source, fileName);
}
